create extension if not exists "pgcrypto";create table if not exists portfolios(id uuid primary key default gen_random_uuid(),user_id uuid not null references auth.users(id) on delete cascade,name text not null,base_currency text not null default 'USD',created_at timestamptz not null default now());create table if not exists accounts(id uuid primary key default gen_random_uuid(),portfolio_id uuid not null references portfolios(id) on delete cascade,user_id uuid not null references auth.users(id) on delete cascade,name text not null,kind text not null default 'BROKERAGE',currency text not null default 'USD',created_at timestamptz not null default now());create table if not exists securities(id uuid primary key default gen_random_uuid(),symbol text not null,name text not null,asset_class text not null,currency text not null default 'USD',exchange text,unique(symbol,exchange));create table if not exists transactions(id uuid primary key default gen_random_uuid(),portfolio_id uuid not null references portfolios(id) on delete cascade,account_id uuid references accounts(id) on delete set null,user_id uuid not null references auth.users(id) on delete cascade,security_id uuid references securities(id) on delete set null,type text not null check(type in ('BUY','SELL','DIVIDEND','DEPOSIT','WITHDRAWAL','FEE','TAX')),trade_date date not null,quantity numeric(28,10),price numeric(28,10),amount numeric(28,10) not null,currency text not null,fee numeric(28,10) not null default 0,tax numeric(28,10) not null default 0,created_at timestamptz not null default now());create index if not exists tx_user_date_idx on transactions(user_id,trade_date desc);alter table portfolios enable row level security;alter table accounts enable row level security;alter table transactions enable row level security;create policy "portfolio_owner" on portfolios for all using(auth.uid()=user_id) with check(auth.uid()=user_id);create policy "account_owner" on accounts for all using(auth.uid()=user_id) with check(auth.uid()=user_id);create policy "transaction_owner" on transactions for all using(auth.uid()=user_id) with check(auth.uid()=user_id);